import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/GPS/","title":"","lang":"en-US","frontmatter":{},"git":{"updatedTime":1615404868000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/Noei"}],"changelog":[{"hash":"6fc2e3bfbc1a5d9a50f12c4124a282d00f430155","time":1615404868000,"email":"logmanxsa@gmail.com","author":"Noei","message":"Create GPS Content"}]},"filePathRelative":"GPS/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h2 id="gps" tabindex="-1"><a class="header-anchor" href="#gps"><span>GPS</span></a></h2><ul><li>Earth Resource Observation System(EROS) = ระบบสังเกตการณ์ทรัพยากรโลก เช่น ดาวเทียม GPS ISS</li><li>EROS Data Informatic Platfrom Service(EDIPS) = บริการข้อมูลและแพลตฟอร์มข้อมูล EROS (Public API)</li><li>Fire Information for Resource Management System(FIRMS) = เผยแพร่ข้อมูลจุดความ ร้อนทั่วโลก อัพเดทภายใน 3 ชั่วโมง สังเกตจากเซ็นเซอร์ the Moderate Resolution Imaging Spectroradiometer (MODIS) บนดาวเทียม Aqua และ Terra และชุดเครื่องวัดรังสีอินฟราเรดที่มองเห็นได้ (VIIRS) ที่อยู่บนดาวเทียม S-NPP และ NOAA 20 Google Point Marker(GPX) = เป็น Schema ของ XML ที่ออกแบบมาเป็นรูปแบบข้อมูล GPS</li><li>Keyhole Markup Language(KML) = ส่วนหนึ่งของเอกสาร XML สำหรับการทำโมเดลและจัดเก็บคุณลักษณะทางภูมิศาสตร์ เช่น จุด เส้น ภาพ รูปทรง สำหรับแสดงบน google earth google map</li><li>Keyhole Markup Zip(KMZ) = zip ของ KML ให้มีขนาดเล็กลง Global Administrative District Map(GADM) คือ การจัดการทำแผนที่เพื่อบ่งบอกเขตปกครองภายในเทศนั้นๆ โดยใช้ความละเอียดเชิงพื้นที่ สูงและชุดคุณลักษณะที่หลากหลาย</li><li>ISO 3166-2 = ส่วนที่ 2 ของมาตรฐาน ISO 3166 อธิบายถึงตำแหน่งส่วนการปกครองต่างๆ ในแต่ละประเทศ หรือเขตการปกครอง อิสระ จุดประสงค์ของการสร้างมาตรฐานเพื่อใช้เป็นคำย่อขนาดสั้น สำหรับสถานที่ ใช้ทั่วโลก ในปัจจุบันมีรหัสทั้ง 3700 รหัส</li><li>Time Zone(TZ) = แผนที่แสดงเขตเวลาบนโลกที่แตกต่างกันแต่ละบริเวณ แต่ละเขตเวลามีความแน่นอนไม่เหมือนกัน</li><li>Universal Time Co-ordinated (UTC) = หน่วยเวลาที่ใช้ในการอ้างอิงการหมุนของโลก โดยใช้เครื่องหมายบวก (+) หรือลบ (-) เทียบจากหน่วยเวลาสากลซึ่งเป็นระบบอ้างอิงจากเวลา GMT</li><li>API code คือ คำสั่ง (Code) ที่อนุญาตให้ software program สามารถสื่อสารระหว่างกันได้</li><li>bounding box คือกล่องสี่เหลี่ยมสำหรับปิดล้อมรอบบริเวณนั้นๆ หรือบริเวณที่ถูกกำหนดหมายเลข ซึ่ง กล่องสี่เหลี่ยมนี้จะช่วยในการคำนวณจุดศูนย์กลาง พื้นที่ ความยาวแกนx-แกนy จุดพิกัด ฯ ของบริเวณหรือวัตถุในภาพที่สนใจ</li></ul><p>Map type แบ่งเป็น 3 แบบ</p><ul><li>Cylindrical Map Projections (ทรงกระบอก) Mercator, Robinson, Goodes homolosine projection.</li><li>Conic Map Projections (ทรงกรวย)</li><li>Azimuthal Map Projection (ลูกโลก)</li></ul>`,4)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};